        // The problem says "aim at any target at moment 0". This implies we can be at target i's position at t=i.t?
        // No, at t=0. So we move from (x_i, y_i) at t=0 to (x_i, y_i) at t_i? Distance is 0.
        // Yes, so any single target is always reachable as a standalone sequence.
        dp[i] = curr.p;

        for j in 0..i {
            let prev = &targets[j];
            let dt = curr.t as f64 - prev.t as f64;
            if dt < 0.0 {
                continue;
            }
            let dist = ((curr.x as f64 - prev.x as f64).powi(2) + (curr.y as f64 - prev.y as f64).powi(2)).sqrt();
            if dist <= dt {
                if dp[j] + curr.p > dp[i] {
                    dp[i] = dp[j] + curr.p;
                }
            }
        }
    }

    let ans = if m == 0 { 0.0 } else { dp.iter().cloned().fold(0.0, f64::max) };

    println!("{:.10}", ans);
}
