    let mut lines = stdin.lock().lines();

    if let Some(Ok(line)) = lines.next() {
        let n: usize = line.trim().parse().unwrap_or(0);
        if n == 0 {
            println!("{:.10}", 0.0);
            return;
        }

        let mut targets = Vec::with_capacity(n);
        for _ in 0..n {
            if let Some(Ok(line)) = lines.next() {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 4 {
