                    let yi: i64 = parts[1].parse().unwrap();
                    let ti: i64 = parts[2].parse().unwrap();
                    let pi: f64 = parts[3].parse().unwrap();
                    targets.push(Target { x: xi, y: yi, t: ti, p: pi });
                }
            }
        }

        // Sort targets by time
        targets.sort_by_key(|t| t.t);

        // dp[i] = maximum expected number of hits ending with the i-th target (as the last hit)
        // We also need to consider the option of not hitting any target (value 0).
        let m = targets.len();
        let mut dp = vec![0.0f64; m];
        let mut best_hit = 0.0;

        for i in 0..m {
            let tm = targets[i].t;
            let tx = targets[i].x;
            let ty = targets[i].y;
            let tp = targets[i].p;

            // Option 1: Don't hit this target at all (or it's not reachable)
            // dp[i] starts as 0.0, meaning we haven't hit any previous target ending here with this as last.
            // But actually, dp[i] should be: max over all previous j such that dist(j, i) <= tm - tj
            // of (dp[j] + tp) assuming we hit j then i. Is it possible to skip the required travel?
            // Yes, if we just jump to i at time tm, cost is distance. Previous state must be achievable.

            // Initialize with just ti (probability of hitting i alone if we start aiming at 0)
            // Actually, problem says "He can aim at any target at the moment 0".
            // This implies at t=0 he can be anywhere.
            // So the first target can always be hit if we position ourselves there at t_i.
            // Cost to reach (xi, yi) from "somewhere at t=0" is just |xi|+|yi|? No.
            // "aim at any target at the moment 0" means at t=0 the sight is at some (x,y).
            // He wants to maximize expected hits.
            // If he chooses to hit target i first, he needs to be at (xi, yi) at ti.
            // Can he be there at time 0? Distance from arbitrary point?
            // Wait, "aim at any target at the moment 0".
            // This usually means the initial position of the sight at t=0 can be chosen arbitrarily.
            // Yes, "He can aim at any target at the moment 0".
            // So for the very first target hit, the travel cost is 0 (we set sight to target i at t=0,
            // wait that's not how time works. Sight moves speed 1. 
            // If at t=0 sight is at (x0, y0), then at time t it can be at any (x,y) such that dist((x0,y0), (x,y)) <= t.
            // Since we can choose (x0, y0) arbitrarily, can we reach ANY target at ANY time ti >= 0?
            // If we pick (x0, y0) = (tx, ty), then dist=0 <= ti. Yes.
            // We can just pick the starting point to be the location of the first target.
            // So the very first target in a sequence is always reachable at its ti regardless of others.
            // The constraint is between two targets j -> i: dist(xj, xi) + dist(yj, yi) <= ti - tj.
            // But the absolute position at t=0 is free. So we don't need to check distance from origin or start.
            // We just need to ensure feasibility with previous targets.

            dp[i] = tp; // At least this target alone is hit.

            // Try to extend from previous targets
            for j in 0..i {
                let t_prev = targets[j].t;
                let txj = targets[j].x;
                let tyj = targets[j].y;

                let dt = (targets[i].t - t_prev) as f64;
                let d = ((tx - txj) as f64).powi(2) + ((ty - tyj) as f64).powi(2);
                let dist = d.sqrt();

                // Check if time allows
                if dt >= dist {
                    let val = dp[j] + tp;
                    if val > dp[i] {
                        dp[i] = val;
                    }
                }
            }

            // Update global maximum
            if dp[i] > best_hit {
                best_hit = dp[i];
            }
        }

        println!("{:.10}", best_hit);
    }
}
